insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'ms_madv6_v1'
from (values
('111.29.c.2.A',2,'In a Venn diagram of number sets, the set of whole numbers sits entirely inside the set of integers. What does that show?','["Whole numbers are a subset of the integers.", "The two sets share no numbers.", "Integers are a subset of whole numbers.", "Whole numbers and integers are the same set."]'::jsonb,0,'A circle drawn inside another means every member of the inner set belongs to the outer set.','original'),
('111.29.c.2.A',3,'Which hierarchy lists these sets from smallest to largest: integers, whole numbers, rational numbers?','["whole numbers, rational numbers, integers", "whole numbers, integers, rational numbers", "integers, whole numbers, rational numbers", "rational numbers, integers, whole numbers"]'::jsonb,1,'Whole numbers fit inside integers, and integers fit inside rational numbers.','original'),
('111.29.c.2.B',2,'What is the opposite of -37?','["0", "-73", "37", "-37"]'::jsonb,2,'The opposite of a number is the same distance from 0 on the other side.','original'),
('111.29.c.2.B',3,'What is the absolute value of -4.6?','["0.46", "-4.6", "-5", "4.6"]'::jsonb,3,'Absolute value is distance from 0, so it is never negative.','original'),
('111.29.c.2.C',2,'Which percent equals the fraction 1/4?','["25%", "40%", "14%", "4%"]'::jsonb,0,'1/4 of 100 is 25, so 1/4 = 25%.','original'),
('111.29.c.2.C',3,'A model has 100 squares and 33 1/3 of them are shaded in a pattern of thirds. About what fraction is shaded?','["1/33", "1/3", "3/10", "1/4"]'::jsonb,1,'33 1/3% is the benchmark percent for one third.','original'),
('111.29.c.2.D',2,'Which decimal and percent are equal to 3/5?','["6.0 and 600%", "0.35 and 35%", "0.6 and 60%", "0.3 and 30%"]'::jsonb,2,'3/5 = 6/10 = 0.6 = 60%.','original'),
('111.29.c.2.D',3,'A recipe uses 0.125 of a cup of oil. What fraction of a cup is this?','["12/5", "1/125", "1/5", "1/8"]'::jsonb,3,'0.125 = 125/1000 = 1/8.','original'),
('111.29.c.2.E',3,'Mia ate 7/10 of a pizza and Jay ate 70% of an identical pizza. How do their amounts compare?','["They ate equal amounts.", "Jay ate more.", "Mia ate more.", "They ate different amounts but cannot tell which is more."]'::jsonb,0,'7/10 = 0.7 = 70% of the same size whole.','original'),
('111.29.c.2.E',3,'Which three values name the same part of a whole?','["3/20, 0.3, 30%", "3/20, 0.15, 15%", "3/20, 1.5, 15%", "3/20, 0.015, 1.5%"]'::jsonb,1,'3/20 = 15/100 = 0.15 = 15%.','original'),
('111.29.c.2.F',2,'On a horizontal number line, which number is farthest to the left?','["-2", "5", "-9", "0"]'::jsonb,2,'Numbers farther left are less.','original'),
('111.29.c.2.H',2,'In which quadrant is the point (-4, 6)?','["Quadrant I", "Quadrant III", "Quadrant IV", "Quadrant II"]'::jsonb,3,'Negative x and positive y puts a point in Quadrant II.','original'),
('111.29.c.2.H',3,'What are the coordinates of the point 5 units right of the origin and 3 units down?','["(5, -3)", "(-3, 5)", "(-5, 3)", "(3, -5)"]'::jsonb,0,'Move right for x and down for negative y.','original'),
('111.29.c.3.A',3,'Dividing by 3/4 gives the same result as multiplying by:','["-3/4", "4/3", "1/3", "3/4"]'::jsonb,1,'Dividing by a rational number equals multiplying by its reciprocal.','original'),
('111.29.c.3.A',3,'Which expression has the same value as 6 ÷ 2/5?','["2/5 ÷ 6", "6 ÷ 5/2", "6 × 5/2", "6 × 2/5"]'::jsonb,2,'Change the divisor to its reciprocal and multiply.','original'),
('111.29.c.3.B',3,'Without calculating, which product is greater than 40?','["40 × 3/4", "40 × 1/2", "40 × 9/10", "40 × 1 1/4"]'::jsonb,3,'Multiplying by a number greater than 1 increases the quantity.','original'),
('111.29.c.3.B',3,'Maya multiplies 18 by 5/6. Will the product be less than, equal to or greater than 18?','["less than 18", "equal to 18", "greater than 18", "impossible to tell"]'::jsonb,0,'5/6 is less than 1.','original'),
('111.29.c.3.C',2,'The fraction 7/8 represents the same number as which division?','["7 × 8", "7 ÷ 8", "8 ÷ 7", "8 - 7"]'::jsonb,1,'The fraction bar means divide numerator by denominator.','original'),
('111.29.c.3.C',3,'Five friends share 3 sandwiches equally. How much does each friend get?','["1/5 of a sandwich", "3 sandwiches", "3/5 of a sandwich", "5/3 of a sandwich"]'::jsonb,2,'3 ÷ 5 = 3/5.','original'),
('111.29.c.3.D',2,'A model shows 5 positive counters and 8 negative counters. What integer does it represent?','["-13", "3", "13", "-3"]'::jsonb,3,'Pair 5 positives with 5 negatives, leaving 3 negatives.','original'),
('111.29.c.3.D',3,'Which action on a number line models -2 + 6?','["Start at -2 and move 6 units right.", "Start at 2 and move 6 units left.", "Start at -6 and move 2 units right.", "Start at 0 and move 8 units right."]'::jsonb,0,'Adding a positive moves right.','original'),
('111.29.c.3.E',2,'What is -14 + 9?','["23", "-5", "5", "-23"]'::jsonb,1,'Subtract the absolute values and keep the sign of the larger one.','original'),
('111.29.c.3.E',3,'What is -8 + (-7 × -3)?','["-29", "29", "13", "-13"]'::jsonb,2,'-8 + 21 = 13.','original'),
('111.29.c.3.F',4,'What is -1.5 × 0.4?','["-6", "0.6", "-0.06", "-0.6"]'::jsonb,3,'1.5 × 0.4 = 0.6, and a negative times a positive is negative.','original'),
('111.29.c.3.G',3,'Which is the value of 4 + 3² × 2?','["22", "49", "98", "26"]'::jsonb,0,'Exponent first: 9; then 9 × 2 = 18; then 4 + 18 = 22.','original'),
('111.29.c.3.G',4,'The prime factorization of 72 is:','["2² × 3³", "2³ × 3²", "2 × 6²", "8 × 9"]'::jsonb,1,'72 = 8 × 9 = 2³ × 3².','original'),
('111.29.c.3.H',3,'A check register starts at $240. A deposit of $85 is made and a withdrawal of $60 is made. What is the balance?','["$185", "$295", "$265", "$215"]'::jsonb,2,'240 + 85 - 60 = 265.','original'),
('111.29.c.3.H',3,'A register balance is $120. A transfer of $45 out of the account is recorded. What is the new balance?','["$45", "$165", "$120", "$75"]'::jsonb,3,'A transfer out is subtracted.','original'),
('111.29.c.3.I',3,'A student has assets of $1,250 and liabilities of $400. What is the net worth?','["$850", "$1,250", "$400", "$1,650"]'::jsonb,0,'Net worth = assets - liabilities.','original'),
('111.29.c.3.I',3,'Which item is a liability?','["a savings account", "a loan balance owed to a lender", "cash in a wallet", "a bicycle you own"]'::jsonb,1,'Liabilities are amounts you owe.','original'),
('111.29.c.4.A',3,'What is 35% of 80?','["280", "45", "28", "2.8"]'::jsonb,2,'0.35 × 80 = 28.','original'),
('111.29.c.4.A',4,'A jacket sale price is $36 after 40% off the original price. What was the original price?','["$50.40", "$14.40", "$90", "$60"]'::jsonb,3,'Sale price is 60% of the original. 36 ÷ 0.60 = 60.','original'),
('111.29.c.4.B',3,'A game costs $45 and sales tax is 8%. How much is the tax?','["$3.60", "$4.50", "$36", "$0.36"]'::jsonb,0,'0.08 × 45 = 3.60.','original'),
('111.29.c.4.B',4,'A worker earns $520 in a week and 12% is withheld for income tax. How much is withheld?','["$124.80", "$62.40", "$457.60", "$6.24"]'::jsonb,1,'0.12 × 520 = 62.40.','original'),
('111.29.c.5.A',2,'A bag has 12 red and 9 blue marbles. Which ratio compares red to blue?','["9 to 12", "9 to 21", "12 to 9", "12 to 21"]'::jsonb,2,'Ratio of red to blue is 12:9.','original'),
('111.29.c.5.A',3,'The ratio of cats to dogs at a shelter is 5:3. If there are 15 cats, how many dogs are there?','["25", "3", "5", "9"]'::jsonb,3,'15 = 5 × 3, so dogs = 3 × 3 = 9.','original'),
('111.29.c.5.B',2,'Which is a rate?','["240 miles in 4 hours", "5 cups and 5 cups", "12 red apples and 12 green apples", "3 boys and 3 girls"]'::jsonb,0,'A rate compares two quantities with different units.','original'),
('111.29.c.5.B',3,'A hose fills 30 gallons in 6 minutes. What is the rate per minute?','["36 gallons per minute", "5 gallons per minute", "0.2 gallons per minute", "24 gallons per minute"]'::jsonb,1,'30 ÷ 6 = 5.','original'),
('111.29.c.5.C',3,'A 10-by-10 grid has 45 squares shaded. Which percent does the shading represent?','["10%", "55%", "45%", "4.5%"]'::jsonb,2,'45 out of 100 squares is 45%.','original'),
('111.29.c.5.C',3,'The ratio 3:4 written as a fraction of the total (3 + 4 parts) shows the first part is:','["4/7", "3/12", "3/4", "3/7"]'::jsonb,3,'First part over total parts is 3/7.','original'),
('111.29.c.5.D',3,'A map uses a scale of 1 inch = 15 miles. Two towns are 4 inches apart on the map. How far apart are they?','["60 miles", "3.75 miles", "19 miles", "15 miles"]'::jsonb,0,'4 × 15 = 60.','original'),
('111.29.c.5.D',3,'A photo is enlarged by a scale factor of 3. A 4-inch side becomes:','["3 inches", "12 inches", "1.33 inches", "7 inches"]'::jsonb,1,'4 × 3 = 12.','original'),
('111.29.c.6.A',3,'A recipe uses 3 cups of flour for 24 cookies. About how much flour is needed for 60 cookies?','["18 cups", "6 cups", "7.5 cups", "9 cups"]'::jsonb,2,'60 cookies is 2.5 times 24, so 3 × 2.5 = 7.5.','original'),
('111.29.c.6.A',3,'Store A sells 4 pens for $3.20 and store B sells 6 pens for $4.50. Which has the better price per pen?','["They are the same", "Store B at $0.80", "Store A at $0.80", "Store B at $0.75"]'::jsonb,3,'Store A is $0.80 per pen and store B is $0.75.','original'),
('111.29.c.6.B',3,'A runner covers 9 miles in 1.5 hours. What is the unit rate in miles per hour?','["6", "13.5", "0.17", "7.5"]'::jsonb,0,'9 ÷ 1.5 = 6.','original'),
('111.29.c.6.B',3,'A 12-ounce box of cereal costs $4.20. What is the unit price per ounce?','["$2.86", "$0.35", "$0.28", "$3.50"]'::jsonb,1,'4.20 ÷ 12 = 0.35.','original'),
('111.29.c.6.C',2,'How many centimeters are in 3.5 meters?','["3,500", "35", "350", "0.035"]'::jsonb,2,'1 meter = 100 centimeters.','original'),
('111.29.c.6.C',3,'There are about 2.54 centimeters in 1 inch. About how many centimeters are in 10 inches?','["12.54", "3.94", "254", "25.4"]'::jsonb,3,'10 × 2.54 = 25.4.','original'),
('111.29.c.7.A',2,'Which is an expression and NOT an equation?','["7n - 3", "7n - 3 = 4", "n = 2", "2n = 8"]'::jsonb,0,'An expression has no equals sign.','original'),
('111.29.c.7.B',3,'Which expression is NOT equivalent to 3x + 6?','["x + x + x + 6", "3(x + 6)", "6 + 3x", "3(x + 2)"]'::jsonb,1,'3(x + 6) = 3x + 18.','original'),
('111.29.c.7.C',3,'Which property shows that 4 + (x + 9) = (4 + x) + 9?','["commutative property", "inverse property", "associative property", "identity property"]'::jsonb,2,'Regrouping terms is the associative property.','original'),
('111.29.c.7.C',3,'Which property is used when 5 × y is rewritten as y × 5?','["associative property", "distributive property", "inverse property", "commutative property"]'::jsonb,3,'Changing order is the commutative property.','original'),
('111.29.c.8.A',3,'A gym charges a $20 sign-up fee plus $15 per month. Which equation gives the total cost C after m months?','["C = 15m + 20", "C = 15 + 20 + m", "C = 35m", "C = 20m + 15"]'::jsonb,0,'Fixed fee plus rate times months.','original'),
('111.29.c.8.A',3,'You have $50 and can spend at most $8 per ticket. Which inequality shows how many tickets t you can buy?','["8 + t ≤ 50", "8t ≤ 50", "t ≤ 8", "8t ≥ 50"]'::jsonb,1,'Total cost must not exceed $50.','original'),
('111.29.c.8.B',3,'Which situation matches the equation 4n = 36?','["You buy 36 items for $4 total.", "You had $4 and spent $36.", "4 friends share $36 equally and each pays n.", "A $4 fee is added to a $36 bill."]'::jsonb,2,'Four equal parts total 36 gives 4n = 36.','original'),
('111.29.c.8.B',3,'Which problem matches x + 12 = 30?','["A class has 12 students and loses x.", "30 students are split into 12 groups.", "A class has 30 students and loses 12 more.", "A class had x students, 12 joined and now there are 30."]'::jsonb,3,'Starting amount plus 12 equals 30.','original'),
('111.29.c.8.C',3,'Which graph shows x > 4 on a number line?','["an open circle at 4 with an arrow pointing right", "a closed circle at 4 with an arrow pointing left", "an open circle at 4 with an arrow pointing left", "a closed circle at 4 with an arrow pointing right"]'::jsonb,0,'Open circle: 4 not included. Arrow right: values greater than 4.','original'),
('111.29.c.8.C',3,'A number line shows a closed circle at 2 with an arrow pointing left. Which inequality does it show?','["x ≥ 2", "x ≤ 2", "x < 2", "x > 2"]'::jsonb,1,'Closed circle includes 2; arrow left means less.','original'),
('111.29.c.8.D',2,'Solve: x + 9 = 21','["30", "11", "12", "-12"]'::jsonb,2,'Subtract 9 from both sides.','original'),
('111.29.c.8.D',3,'Solve: 6x = 84','["90", "78", "504", "14"]'::jsonb,3,'Divide both sides by 6.','original'),
('111.29.c.8.E',3,'Solve: 3x + 5 = 26','["7", "10", "31/3", "21"]'::jsonb,0,'Subtract 5 to get 3x = 21, then divide by 3.','original'),
('111.29.c.8.E',4,'Solve: 2x - 7 > 9','["x > 16", "x > 8", "x < 8", "x > 1"]'::jsonb,1,'Add 7 to get 2x > 16, then divide by 2.','original'),
('111.29.c.8.F',2,'Which value makes 2x + 3 = 15 true?','["x = 4", "x = 12", "x = 6", "x = 9"]'::jsonb,2,'2(6) + 3 = 15.','original'),
('111.29.c.8.F',3,'Which value makes x - 4 < 3 true?','["x = 8", "x = 7", "x = 10", "x = 6"]'::jsonb,3,'6 - 4 = 2 which is less than 3; 7 - 4 = 3 is not less than 3.','original'),
('111.29.c.9.A',2,'A table pairs the hours a person works with a paycheck amount. Which quantity is the dependent quantity?','["pay earned", "the number of workers", "hours worked", "the hourly rate"]'::jsonb,0,'Pay depends on hours worked.','original'),
('111.29.c.9.A',3,'In a graph of distance traveled versus time, which axis usually shows the independent quantity?','["neither axis", "the horizontal axis (time)", "both axes", "the vertical axis (distance)"]'::jsonb,1,'Independent quantity goes on the horizontal axis.','original'),
('111.29.c.9.B',3,'x: 1, 2, 3, 4 and y: 6, 12, 18, 24. Which equation matches?','["y = 6 + x", "y = x + 5", "y = 6x", "y = 12x"]'::jsonb,2,'Each y is 6 times x.','original'),
('111.29.c.9.B',3,'x: 2, 4, 6, 8 and y: 5, 7, 9, 11. Which equation matches?','["y = x - 3", "y = 3x", "y = 2x + 1", "y = x + 3"]'::jsonb,3,'Each y is 3 more than x.','original'),
('111.29.c.9.C',3,'Pencils cost $0.25 each. Which equation shows the cost y of x pencils?','["y = 0.25x", "y = x ÷ 0.25", "y = x + 0.25", "y = 0.25 + x"]'::jsonb,0,'Cost is a constant rate times the number.','original'),
('111.29.c.9.C',3,'A plant is 8 cm tall and grows 3 cm. Which equation shows the new height y when the original is x?','["y = 3x", "y = x + 3", "y = x - 3", "y = 8x"]'::jsonb,1,'Add the growth to the original height.','original'),
('111.29.c.9.D',3,'Rule A: y = 2x. Rule B: y = x + 2. For which x are the outputs equal?','["x = 1", "x = 0", "x = 2", "x = 3"]'::jsonb,2,'2(2) = 4 and 2 + 2 = 4.','original'),
('111.29.c.9.D',4,'Compare y = 3x and y = x + 6. When x = 5 which output is greater?','["They are equal", "y = x + 6", "Cannot be determined", "y = 3x"]'::jsonb,3,'3(5) = 15 and 5 + 6 = 11.','original'),
('111.29.c.11.A',3,'A parallelogram can be cut and rearranged into a rectangle with the same base and height. What formula does this model?','["A = b × h", "A = b + h", "A = 2b + 2h", "A = 1/2 × b × h"]'::jsonb,0,'The rectangle has area base times height.','original'),
('111.29.c.11.A',3,'Two identical triangles form a parallelogram. The area of one triangle is therefore:','["2 × b × h", "1/2 × b × h", "b + h", "b × h"]'::jsonb,1,'Half the parallelogram''s area.','original'),
('111.29.c.11.B',3,'A triangle has area 30 square units and base 12 units. Which equation finds its height h?','["12 × h = 30", "1/2 × 12 + h = 30", "1/2 × 12 × h = 30", "12 + h = 30"]'::jsonb,2,'Area of a triangle is 1/2 × base × height.','original'),
('111.29.c.11.B',3,'A rectangle has area 56 and width 7. Which equation finds the length?','["7 + l = 56", "7 - l = 56", "l ÷ 7 = 56", "7 × l = 56"]'::jsonb,3,'Area equals length times width.','original'),
('111.29.c.12.A',3,'Two angles of a triangle measure 48° and 67°. What is the third angle?','["65°", "45°", "85°", "115°"]'::jsonb,0,'180 - 48 - 67 = 65.','original'),
('111.29.c.12.A',3,'In a triangle, the largest angle is opposite the:','["any side", "longest side", "shortest side", "middle side"]'::jsonb,1,'The longest side is across from the largest angle.','original'),
('111.29.c.12.B',3,'A trapezoid has bases 6 and 10 and height 4. What is its area?','["40 square units", "24 square units", "32 square units", "64 square units"]'::jsonb,2,'1/2 × (6 + 10) × 4 = 32.','original'),
('111.29.c.12.B',3,'A parallelogram has base 9 and height 5. What is its area?','["90 square units", "22.5 square units", "14 square units", "45 square units"]'::jsonb,3,'9 × 5 = 45.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Mathematics' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'ms_madv6_v1'
from (values
('111.29.c.12.C',3,'A right rectangular prism is 4 by 3 by 5. What is its volume?','["60 cubic units", "12 cubic units", "47 cubic units", "94 cubic units"]'::jsonb,0,'4 × 3 × 5 = 60.','original'),
('111.29.c.12.C',4,'A triangular prism has a triangular base with area 14 square units and height 6 units. What is its volume?','["42 cubic units", "84 cubic units", "168 cubic units", "20 cubic units"]'::jsonb,1,'Volume = base area × height = 14 × 6.','original'),
('111.29.c.12.D',3,'Two angles in a triangle are x and 2x and the third is 60°. Which equation finds x?','["x + 2x = 60", "x + 2x + 60 = 360", "x + 2x + 60 = 180", "2x + 60 = 180"]'::jsonb,2,'Angles of a triangle add to 180°.','original'),
('111.29.c.12.D',3,'Two angles are supplementary. One is 3x and the other is 40°. Which equation fits?','["3x + 40 = 360", "3x = 40", "3x + 40 = 90", "3x + 40 = 180"]'::jsonb,3,'Supplementary angles add to 180°.','original'),
('111.29.c.13.A',2,'Which question will produce data with variability?','["How many minutes did each student spend on homework last night?", "How many days are in a week?", "How many sides does a triangle have?", "What is 5 + 5?"]'::jsonb,0,'Answers vary from student to student.','original'),
('111.29.c.13.A',2,'Which question has just one correct answer, so no variability?','["How many pets does each classmate have?", "How many months are in a year?", "How long is each student''s commute?", "How tall are the students in your class?"]'::jsonb,1,'A fixed fact has no variability.','original'),
('111.29.c.13.B',3,'A box plot uses five numbers. Which is NOT one of them?','["median", "minimum", "mean", "maximum"]'::jsonb,2,'A box plot shows min, Q1, median, Q3 and max.','original'),
('111.29.c.13.B',3,'Which display groups data into intervals using bars with no gaps?','["circle graph", "stem-and-leaf plot", "dot plot", "histogram"]'::jsonb,3,'A histogram shows frequencies in intervals.','original'),
('111.29.c.14.A',3,'A dot plot has most dots on the left and a long tail to the right. The shape is:','["skewed right", "uniform", "symmetric", "skewed left"]'::jsonb,0,'The tail points right.','original'),
('111.29.c.14.A',3,'In a dot plot, data spread from 2 to 18 describes the:','["shape only", "spread of the distribution", "center", "mode only"]'::jsonb,1,'Spread describes how far data extend.','original'),
('111.29.c.14.B',3,'What is the median of 3, 7, 8, 12, 15?','["9", "7", "8", "12"]'::jsonb,2,'The middle value is 8.','original'),
('111.29.c.14.B',3,'For the data 4, 6, 8, 10, 12, what is the range?','["6", "10", "12", "8"]'::jsonb,3,'12 - 4 = 8.','original'),
('111.29.c.14.C',3,'A stem-and-leaf plot has stem 3 and leaves 2, 5, 5. What data values are shown?','["32, 35, 35", "325", "3, 2, 5, 5", "23, 53, 53"]'::jsonb,0,'Stem is tens digit, leaves are ones digits.','original'),
('111.29.c.14.C',3,'In a histogram, the tallest bar represents the interval with the:','["highest value", "highest frequency", "median value", "lowest frequency"]'::jsonb,1,'Bar height shows frequency.','original'),
('111.29.c.14.D',3,'A bar graph shows soccer 18, tennis 12, golf 6. How many more chose soccer than golf?','["24", "6", "12", "36"]'::jsonb,2,'18 - 6 = 12.','original'),
('111.29.c.14.E',4,'Two box plots show test scores. One class has a median of 82 and the other has a median of 74. Which class has the higher center?','["They are equal", "the class with median 74", "Cannot tell from medians", "the class with median 82"]'::jsonb,3,'Compare medians for centers.','original'),
('111.29.c.14.E',4,'Comparing two dot plots, one is tightly clustered and the other is wide. Which comparison does this describe?','["spread", "mode", "range of a single point", "center"]'::jsonb,0,'Cluster width describes spread.','original'),
('111.29.c.14.F',2,'Favorite pets in a class: 8 students chose dogs, 6 cats, 6 fish and 4 birds. What does the mode describe here?','["the category chosen by 6 students", "the category chosen by 8 students", "the category chosen by 4 students", "the total of 24 students"]'::jsonb,1,'The mode is the category chosen most often.','original'),
('111.29.c.14.F',3,'In a survey of 40 students, 10 chose pizza. What percent chose pizza?','["40%", "4%", "25%", "10%"]'::jsonb,2,'10 ÷ 40 = 0.25.','original'),
('111.29.c.15.A',3,'A debit card takes money directly from the:','["credit line", "savings bond", "loan", "checking account"]'::jsonb,3,'A debit card draws on checking account funds.','original'),
('111.29.c.15.A',3,'When comparing checking accounts, a student should look at monthly fees and:','["minimum balance rules", "the color of the checks", "the bank''s logo", "branch decor"]'::jsonb,0,'Fees and rules affect cost.','original'),
('111.29.c.15.B',3,'Which payment method lets you pay later and may charge interest?','["prepaid gift card", "credit card", "debit card", "cash"]'::jsonb,1,'Credit is borrowed money.','original'),
('111.29.c.15.B',3,'Which payment method cannot overdraw beyond the loaded amount?','["credit card", "line of credit", "prepaid card", "loan"]'::jsonb,2,'Prepaid funds limit spending.','original'),
('111.29.c.15.D',3,'A credit report lists a person''s accounts and:','["weight", "favorite stores", "grades", "payment history"]'::jsonb,3,'Reports list accounts and payment behavior.','original'),
('111.29.c.15.D',4,'Most negative items on a credit report are kept for about:','["seven years", "two days", "forty years", "one month"]'::jsonb,0,'Many entries remain for around seven years.','original'),
('111.29.c.15.E',3,'Why do lenders check a borrower''s credit report?','["to learn his favorite music", "to judge how likely the borrower is to repay", "to set his height", "to choose his hobby"]'::jsonb,1,'Lenders assess risk.','original'),
('111.29.c.15.E',3,'How does a borrower benefit from checking their own credit report?','["They can lower taxes", "They can change their address legally", "They can find and fix errors.", "They can skip repayments"]'::jsonb,2,'Reviewing reports catches mistakes.','original'),
('111.29.c.15.F',2,'Which way to pay for college does NOT have to be repaid?','["a credit card balance", "a student loan", "a payday loan", "a scholarship"]'::jsonb,3,'Scholarships and many grants are gifts.','original'),
('111.29.c.15.F',3,'A work-study program helps pay for college by:','["giving students a part-time job", "lowering taxes", "creating a loan with no interest", "canceling tuition"]'::jsonb,0,'Work-study provides wages for campus jobs.','original'),
('111.29.c.15.G',3,'On average, occupations that require more post-secondary education tend to have:','["the same salary always", "higher annual salaries", "lower annual salaries", "no salary"]'::jsonb,1,'More education generally leads to higher pay.','original'),
('111.29.c.15.G',3,'A job requiring a vocational certificate usually needs:','["no training at all", "a law degree", "specific training after high school", "a doctorate"]'::jsonb,2,'Certificates are trade-focused training.','original'),
('111.29.c.2.G',4,'Place these in order from least to greatest: -0.75, -3/4 of 2, 1/3, -1/5.','["-0.75, -3/2, -1/5, 1/3", "-1/5, -0.75, -3/2, 1/3", "1/3, -1/5, -0.75, -3/2", "-3/2, -0.75, -1/5, 1/3"]'::jsonb,3,'-3/4 of 2 is -1.5. Then -1.5 < -0.75 < -0.2 < 0.33.','original'),
('111.29.c.2.G',3,'A scientist records temperatures -2.4, 0.5, -2.04 and 1/4 degrees. Which is the coldest?','["-2.4", "-2.04", "0.5", "1/4"]'::jsonb,0,'The most negative value is farthest left on the number line.','original'),
('111.29.c.15.C',3,'A teen makes every payment on a small loan on time for two years. What is the likely effect on the teen''s credit history?','["It is erased.", "It becomes stronger and shows reliable repayment.", "It has no information.", "It becomes weaker."]'::jsonb,1,'Consistent on-time payments are recorded as positive history.','original'),
('111.29.c.15.C',3,'Which item is most likely to hurt a person''s credit history?','["paying a utility bill early", "keeping a low balance", "missing several credit card payments", "reviewing a credit report"]'::jsonb,2,'Late and missed payments are reported negatively.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Mathematics' and d.language = 'en'
on conflict (fingerprint) do nothing;
